  }

  /** helper function to set the values of all input ports.
   * @param comfortDemand payload for data port comfortDemand
   * @param visibilityDemand payload for data port visibilityDemand
   * @param recoveryDecision payload for data port recoveryDecision
   */
  def put_concrete_inputs(comfortDemand : HVAC_Energy_Interface_Supervisor.ComfortDemand.Type,
                          visibilityDemand : HVAC_Energy_Interface_Supervisor.VisibilityDemand.Type,
                          recoveryDecision : HVAC_Energy_Interface_Supervisor.RecoveryDecision.Type): Unit = {
    put_comfortDemand(comfortDemand)
    put_visibilityDemand(visibilityDemand)
    put_recoveryDecision(recoveryDecision)
  }


  /** helper function to check ServicePriorityArbiter_climateSupervisionProcess_servicePriorityArbiter's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param serviceSelection method that will be called with the value of the outgoing data
   *        port 'serviceSelection'.
   */
  def check_concrete_output(serviceSelection: HVAC_Energy_Interface_Supervisor.ServiceSelection => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val serviceSelectionValue: HVAC_Energy_Interface_Supervisor.ServiceSelection = get_serviceSelection().get
    if(!serviceSelection(serviceSelectionValue)) {
      testFailures = testFailures :+ st"'serviceSelection' did not match expected: value of the outgoing data port is ${serviceSelectionValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_comfortDemand(value : HVAC_Energy_Interface_Supervisor.ComfortDemand.Type): Unit = {
