  }

  // getter for out DataPort
  def get_serviceSelection(): Option[HVAC_Energy_Interface_Supervisor.ServiceSelection] = {
    val value: Option[HVAC_Energy_Interface_Supervisor.ServiceSelection] = get_serviceSelection_payload() match {
