      case _ => None[HVAC_Energy_Interface_Supervisor.ServiceSelection]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_serviceSelection_payload(): Option[HVAC_Energy_Interface_Supervisor.ServiceSelection_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.HVACSupervisor_Instance_climateSupervisionProcess_servicePriorityArbiter.initialization_api.serviceSelection_Id).asInstanceOf[Option[HVAC_Energy_Interface_Supervisor.ServiceSelection_Payload]]
